"""Write an offline, frame-inspectable asset gallery; no pet feature code."""
import json
from pathlib import Path
base=Path(__file__).resolve().parent
m=json.loads((base/'ps1/manifest.json').read_text())
data={'routines':m['routines'],'clips':{c['id']:{k:c[k] for k in ['id','phase','frameCount','frameDurationsMs','file','from','to','creation','derivedFrom']} for c in m['clips']},'sequences':m['sequences'],'transitions':[{'id':c['id'],'name':c['id'].replace('-',' ').title(),'kind':'transition','pose':c['from']+' → '+c['to'],'clips':[c['id']]} for c in m['clips'] if c['routine']=='transition']}
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kōくん — complete animation library</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#eee7d8;color:#243344;font:15px/1.5 system-ui,sans-serif}main{max-width:1300px;margin:auto;padding:30px 24px}h1{font:600 38px/1.15 Georgia,serif;margin:10px 0 14px}h2{font:600 24px Georgia,serif;margin:0 0 8px}h3{font:600 30px Georgia,serif}.eyebrow{font:12px monospace;letter-spacing:2px;color:#a14029}.intro{max-width:850px}.summary{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}.summary span{background:#fffaf0;border:1px solid #c4b79d;padding:8px 12px;border-radius:6px}.toolbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:12px 0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:14px}article{background:#fffaf0;border:1px solid #c4b79d;border-radius:8px;padding:16px;min-width:0}.stage{height:300px;display:flex;align-items:center;justify-content:center;overflow:hidden;border:1px solid #ccc0aa}.stage img{display:block;object-fit:contain;image-rendering:pixelated;max-width:100%;max-height:100%}.checker{background-color:#f2f2ef;background-image:linear-gradient(45deg,#d4d4d0 25%,transparent 25%),linear-gradient(-45deg,#d4d4d0 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#d4d4d0 75%),linear-gradient(-45deg,transparent 75%,#d4d4d0 75%);background-size:24px 24px;background-position:0 0,0 12px,12px -12px,-12px 0}.light{background:#fff}.dark{background:#1e2835}.green{background:#b4ccc1}.meta{font-size:12px;color:#59645f}.controls{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin:12px 0}button,select{font:13px system-ui;color:#243344;background:#fffaf0;border:1px solid #8b968b;padding:6px 8px;border-radius:4px}button{cursor:pointer}button[aria-pressed=true]{background:#243344;color:#fff}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #a14029;outline-offset:3px}label{font-size:12px}input[type=range]{width:100%;accent-color:#a14029}.readout{font:12px monospace;min-height:36px}.links{font-size:12px;line-height:1.8}a{color:#963b27}.wide{width:100%;height:auto}footer{margin-top:30px;padding-top:20px;border-top:1px solid #c4b79d}.sequences{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.sequences img{width:256px;height:256px;object-fit:contain;image-rendering:pixelated}.hidden{display:none!important}@media(max-width:1050px){.grid,.sequences{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:680px){main{padding:20px 12px}.grid,.sequences{grid-template-columns:1fr}h1{font-size:30px}.stage{height:300px}}
</style><main><div class="eyebrow">KŌ · V1.3 · ANIMATION ASSETS</div><h1>Kōくん, in polygons.</h1><p class="intro">The complete PS1 Kōくん animation library. Four limbs total—two forelimbs and two hindlimbs—and three tails. Inspect each frame, slow the motion, mirror it, and test transparency on different backgrounds.</p><div class="summary"><span>24 routines</span><span>56 combinable clips</span><span>672 transparent frames</span><span>256 × 256 source frames</span></div>
<div class="toolbar" aria-label="Preview background"><strong>Background</strong><button data-bg="checker" aria-pressed="true">Checkerboard</button><button data-bg="light" aria-pressed="false">Light</button><button data-bg="dark" aria-pressed="false">Dark</button><button data-bg="green" aria-pressed="false">Green</button></div><div class="toolbar"><label>Show <select id="filter"><option value="all">All routines</option><option value="travel">Travel</option><option value="activity">Props and costumes</option><option value="loop">Quiet loops</option><option value="one-shot">Pet gestures</option><option value="transition">Shared transitions</option></select></label><button id="pauseAll">Pause all</button><button id="playAll">Play all</button></div><section id="cards" class="grid" aria-label="All animation routines"></section>
<h3>Six shared transitions</h3><section id="transitions" class="grid" aria-label="Shared pose transitions"></section><h3>Connected sequences</h3><p>These combine compatible clips. These exercise shared poses and activity joins. The extension also applies roaming, dragging and hover lookups.</p><section id="sequences" class="sequences"></section><h3>All 24 routines</h3><a href="ps1/contact-sheet.png"><img class="wide" src="ps1/contact-sheet.png" alt="Contact sheet of all 24 routines"></a><footer><p><a href="ps1/runtime/manifest.json">Asset manifest</a> · <a href="ps1/verification.json">Verification report</a> · <a href="ps1/audit/straw-hat-adventurer-loop.png">Adventurer frame review</a> · <a href="ps1/contact-sheet.png">All routine contact sheet</a> · <a href="ps1/spec.json">Production and reuse specification</a> · <a href="README.md">Production notes</a> · <a href="ps1/references/approved-design.png">Character references</a></p><p>Generated artwork, exact shared poses, and reversed entry/exit motions. Frame inspection pauses playback. Props and costumes belong only to their routines; Kō’s permanent design has no collar.</p></footer></main><script>
const DATA=__DATA__;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const players=[];
function addPlayer(r,target='#cards'){
 const card=document.createElement('article');card.dataset.kind=r.kind;
 card.innerHTML='<h2></h2><p class="meta"></p><div class="stage checker"><img width="256" height="256"></div><div class="controls"><button class="play">Pause</button><button class="prev" aria-label="Previous frame">◀</button><button class="next" aria-label="Next frame">▶</button><select class="phase" aria-label="Animation phase"><option value="all">Full routine</option></select></div><div class="controls"><label>Speed <select class="speed"><option value="1">1×</option><option value="0.5">½×</option><option value="0.25">¼×</option></select></label><label>Size <select class="size"><option>96</option><option>128</option><option selected>256</option><option>384</option></select> px</label><label><input class="mirror" type="checkbox"> Mirror</label></div><input class="scrub" type="range" min="0" value="0" aria-label="Inspect animation frame"><div class="readout"></div><p class="links"></p>';
 card.querySelector('h2').textContent=r.name;card.querySelector('.meta').textContent=r.clips.length+' clip'+(r.clips.length>1?'s':'')+' · '+r.pose+' · 4 limbs / 3 tails';
 const img=card.querySelector('img');img.alt=r.name+' animation';const phase=card.querySelector('.phase');r.clips.forEach(id=>{const o=document.createElement('option');o.value=id;o.textContent=DATA.clips[id].phase;phase.append(o)});
 const links=card.querySelector('.links');if(r.reviewPreview){const a=document.createElement('a');a.href=r.reviewPreview;a.textContent='Transparent animated preview';links.append(a);}r.clips.forEach(id=>{links.append(' · ');const link=document.createElement('a');link.href='ps1/runtime/'+DATA.clips[id].file;link.textContent=DATA.clips[id].phase+' sprite strip';links.append(link)});
 let timeline=[],position=0,playing=!reduced,speed=1,timer,visible=true;
 const scrub=card.querySelector('.scrub'),button=card.querySelector('.play');
 function rebuild(){timeline=[];(phase.value==='all'?r.clips:[phase.value]).forEach(id=>{const c=DATA.clips[id];for(let i=0;i<c.frameCount;i++)timeline.push({id,i,ms:c.frameDurationsMs[i],phase:c.phase})});position=0;scrub.max=timeline.length-1;render()}
 function render(){const f=timeline[position];img.src='ps1/frames/'+f.id+'/'+String(f.i).padStart(2,'0')+'.png';scrub.value=position;card.querySelector('.readout').textContent=f.phase+' · frame '+(f.i+1)+'/12 · routine frame '+(position+1)+'/'+timeline.length;button.textContent=playing?'Pause':'Play'}
 function schedule(){clearTimeout(timer);timer=setTimeout(()=>{if(playing&&visible){position=(position+1)%timeline.length;render()}schedule()},playing&&visible?timeline[position].ms/speed:200)}
 function setPlaying(value){playing=value;render();schedule()}
 button.onclick=()=>setPlaying(!playing);card.querySelector('.prev').onclick=()=>{playing=false;position=(position-1+timeline.length)%timeline.length;render()};card.querySelector('.next').onclick=()=>{playing=false;position=(position+1)%timeline.length;render()};scrub.oninput=()=>{playing=false;position=Number(scrub.value);render()};phase.onchange=()=>{rebuild();schedule()};card.querySelector('.speed').onchange=e=>{speed=Number(e.target.value);schedule()};card.querySelector('.size').onchange=e=>{img.width=img.height=Number(e.target.value);card.querySelector('.stage').style.height=Math.max(300,Number(e.target.value)+24)+'px'};card.querySelector('.mirror').onchange=e=>img.style.transform=e.target.checked?'scaleX(-1)':'';
 const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting});observer.observe(card);rebuild();schedule();document.querySelector(target).append(card);players.push({card,setPlaying});
}
DATA.routines.forEach(r=>addPlayer(r));
DATA.transitions.forEach(r=>addPlayer(r,'#transitions'));
DATA.sequences.forEach(s=>{const card=document.createElement('article'),title=document.createElement('h2'),stage=document.createElement('div'),img=document.createElement('img'),link=document.createElement('a');title.textContent=s.id.replace('sequence-','').replaceAll('-',' ');stage.className='stage checker';img.src=s.preview;img.alt=s.id+' combined sequence';stage.append(img);link.href=s.preview;link.textContent='Open connected preview';card.append(title,stage,link);document.querySelector('#sequences').append(card)});
document.querySelectorAll('[data-bg]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-bg]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('.stage').forEach(s=>{s.classList.remove('checker','light','dark','green');s.classList.add(b.dataset.bg)})});
document.querySelector('#filter').onchange=e=>players.forEach(p=>p.card.classList.toggle('hidden',e.target.value!=='all'&&p.card.dataset.kind!==e.target.value));document.querySelector('#pauseAll').onclick=()=>players.forEach(p=>p.setPlaying(false));document.querySelector('#playAll').onclick=()=>players.forEach(p=>p.setPlaying(true));
</script></html>'''.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('<','\\u003c'))
(base/'ps1-review.html').write_text(page)

print('Wrote ps1-review.html with frame stepping, speed, size, mirror and background controls.')
